func getOrCreateServerUUID(r models.ScanResult, server c.ServerInfo) (serverUUID string) {
	if id, ok := server.UUIDs[r.ServerName]; !ok {
		serverUUID = uuid.GenerateUUID()
	} else {
		matched, err := regexp.MatchString(reUUID, id)
